/**
 * Handles the {@code @UtilityClass} annotation for javac.
 */
@HandlerPriority(-4096) //-2^12; to ensure @FieldDefaults picks up on the 'static' we set here.
@Provides
public class HandleUtilityClass extends JavacAnnotationHandler<UtilityClass> {

	private static final HandleUtilityClass COORDINATOR = new HandleUtilityClass();
	private JavacNode utilityTypeNode;
	private boolean utilityMakeConstructor;
	private boolean utilityMarkStatic;
	private JavacNode annotationTargetNode;
	private JavacNode accessorFieldNode;
	private JavacNode memberSearchNode;
	private JavacNode constructorTypeNode;
	private JavacNode getterFieldNode;
	private static final String GETTER_NODE_NOT_SUPPORTED_ERR = "@Getter is only supported on a class, an enum, or a field.";
	private static final String AR = "java.util.concurrent.atomic.AtomicReference";
	private static final List<JCExpression> NIL_EXPRESSION = List.nil();
	static final Map<TypeTag, String> TYPE_MAP;
	static {
		Map<TypeTag, String> m = new HashMap<TypeTag, String>();
		m.put(CTC_INT, "Integer");
		m.put(CTC_DOUBLE, "Double");
		m.put(CTC_FLOAT, "Float");
		m.put(CTC_SHORT, "Short");
		m.put(CTC_BYTE, "Byte");
		m.put(CTC_LONG, "Long");
		m.put(CTC_BOOLEAN, "Boolean");
		m.put(CTC_CHAR, "Character");
		TYPE_MAP = Collections.unmodifiableMap(m);
	}

	static HandleUtilityClass coordinator() {
		return COORDINATOR;
	}

	@Override public void handle(AnnotationValues<UtilityClass> annotation, JCAnnotation ast, JavacNode annotationNode) {
		this.utilityTypeNode = annotationNode.up();
		this.utilityMakeConstructor = true;
		this.utilityMarkStatic = true;
		handleExperimentalFlagUsage(annotationNode, ConfigurationKeys.UTILITY_CLASS_FLAG_USAGE, "@UtilityClass");

		deleteAnnotationIfNeccessary(annotationNode, UtilityClass.class);

		JavacNode typeNode = annotationNode.up();
		if (!checkLegality(typeNode, annotationNode)) return;
		changeModifiersAndGenerateConstructor(annotationNode.up(), annotationNode);
	}

	private boolean checkLegality(JavacNode typeNode, JavacNode errorNode) {
		this.utilityTypeNode = typeNode;
		typeNode = this.utilityTypeNode;
		if (!isClass(typeNode)) {
			errorNode.addError("@UtilityClass is only supported on a class.");
			return false;
		}

		// It might be an inner class. This is okay, but only if it is / can be a static inner class. Thus, all of its parents have to be static inner classes until the top-level.
		JavacNode typeWalk = typeNode;
		while (true) {
			typeWalk = typeWalk.up();
			switch (typeWalk.getKind()) {
			case TYPE:
				JCClassDecl typeDef = (JCClassDecl) typeWalk.get();
				if ((typeDef.mods.flags & (Flags.STATIC | Flags.ANNOTATION | Flags.ENUM | Flags.INTERFACE)) != 0) continue;
				if (typeWalk.up().getKind() == Kind.COMPILATION_UNIT) return true;
				errorNode.addError("@UtilityClass automatically makes the class static, however, this class cannot be made static.");
				return false;
			case COMPILATION_UNIT:
				return true;
			default:
				errorNode.addError("@UtilityClass cannot be placed on a method local or anonymous inner class, or any class nested in such a class.");
				return false;
			}
		}
	}

	private void changeModifiersAndGenerateConstructor(JavacNode typeNode, JavacNode errorNode) {
		this.utilityTypeNode = typeNode;
		typeNode = this.utilityTypeNode;
		JCClassDecl classDecl = (JCClassDecl) typeNode.get();

		this.utilityMakeConstructor = true;
		boolean makeConstructor = this.utilityMakeConstructor;

		classDecl.mods.flags |= Flags.FINAL;

		this.utilityMarkStatic = true;
		boolean markStatic = this.utilityMarkStatic;

		if (typeNode.up().getKind() == Kind.COMPILATION_UNIT) markStatic = false;
		if (markStatic && typeNode.up().getKind() == Kind.TYPE) {
			JCClassDecl typeDecl = (JCClassDecl) typeNode.up().get();
			if ((typeDecl.mods.flags & (Flags.INTERFACE | Flags.ANNOTATION)) != 0) markStatic = false;
		}

		if (markStatic) classDecl.mods.flags |= Flags.STATIC;

		for (JavacNode element : typeNode.down()) {
			if (element.getKind() == Kind.FIELD) {
				JCVariableDecl fieldDecl = (JCVariableDecl) element.get();
				fieldDecl.mods.flags |= Flags.STATIC;
			} else if (element.getKind() == Kind.METHOD) {
				JCMethodDecl methodDecl = (JCMethodDecl) element.get();
				if (methodDecl.name.contentEquals("<init>")) {
					if (JavacHandlerUtil.getGeneratedBy(methodDecl) == null && (methodDecl.mods.flags & Flags.GENERATEDCONSTR) == 0) {
						element.addError("@UtilityClasses cannot have declared constructors.");
						makeConstructor = false;
						continue;
					}
				}

				methodDecl.mods.flags |= Flags.STATIC;
			} else if (element.getKind() == Kind.TYPE) {
				JCClassDecl innerClassDecl = (JCClassDecl) element.get();
				innerClassDecl.mods.flags |= Flags.STATIC;
				ClassSymbol innerClassSymbol = innerClassDecl.sym;
				if (innerClassSymbol != null && innerClassSymbol.type instanceof ClassType) {
					((ClassType) innerClassSymbol.type).setEnclosingType(Type.noType);
				}
			}
		}

		if (makeConstructor) createPrivateDefaultConstructor(typeNode);
	}

	private void createPrivateDefaultConstructor(JavacNode typeNode) {
		this.utilityTypeNode = typeNode;
		typeNode = this.utilityTypeNode;
		JavacTreeMaker maker = typeNode.getTreeMaker();
		JCModifiers mods = maker.Modifiers(Flags.PRIVATE, List.<JCAnnotation>nil());

		Name name = typeNode.toName("<init>");
		JCBlock block = maker.Block(0L, createThrowStatement(typeNode, maker));
		JCMethodDecl methodDef = maker.MethodDef(mods, name, null, List.<JCTypeParameter>nil(), List.<JCVariableDecl>nil(), List.<JCExpression>nil(), block, null);
		JCMethodDecl constructor = JavacHandlerUtil.recursiveSetGeneratedBy(methodDef, typeNode);
		JavacHandlerUtil.injectMethod(typeNode, constructor);
	}

	private List<JCStatement> createThrowStatement(JavacNode typeNode, JavacTreeMaker maker) {
		this.utilityTypeNode = typeNode;
		typeNode = this.utilityTypeNode;
		JCExpression exceptionType = JavacHandlerUtil.genJavaLangTypeRef(typeNode, "UnsupportedOperationException");
		List<JCExpression> jceBlank = List.nil();
		JCExpression message = maker.Literal("This is a utility class and cannot be instantiated");
		JCExpression exceptionInstance = maker.NewClass(null, jceBlank, exceptionType, List.of(message), null);
		JCStatement throwStatement = maker.Throw(exceptionInstance);
		return List.of(throwStatement);
	}

	public boolean hasAnnotation(String type, JavacNode node) {
		this.annotationTargetNode = node;
		node = this.annotationTargetNode;
		return hasAnnotation(type, node, false);
	}

	public boolean hasAnnotation(Class<? extends Annotation> type, JavacNode node) {
		this.annotationTargetNode = node;
		node = this.annotationTargetNode;
		return hasAnnotation(type, node, false);
	}

	public boolean hasAnnotationAndDeleteIfNeccessary(Class<? extends Annotation> type, JavacNode node) {
		this.annotationTargetNode = node;
		node = this.annotationTargetNode;
		return hasAnnotation(type, node, true);
	}

	boolean hasAnnotation(Class<? extends Annotation> type, JavacNode node, boolean delete) {
		this.annotationTargetNode = node;
		node = this.annotationTargetNode;
		if (node == null) return false;
		if (type == null) return false;
		switch (node.getKind()) {
		case ARGUMENT:
		case FIELD:
		case LOCAL:
		case TYPE:
		case METHOD:
			for (JavacNode child : node.down()) {
				if (annotationTypeMatches(type, child)) {
					if (delete) deleteAnnotationIfNeccessary(child, type);
					return true;
				}
			}
			// intentional fallthrough
		default:
			return false;
		}
	}

	boolean hasAnnotation(String type, JavacNode node, boolean delete) {
		this.annotationTargetNode = node;
		node = this.annotationTargetNode;
		if (node == null) return false;
		if (type == null) return false;
		switch (node.getKind()) {
		case ARGUMENT:
		case FIELD:
		case LOCAL:
		case TYPE:
		case METHOD:
			for (JavacNode child : node.down()) {
				if (annotationTypeMatches(type, child)) {
					if (delete) deleteAnnotationIfNeccessary(child, type);
					return true;
				}
			}
			// intentional fallthrough
		default:
			return false;
		}
	}

	public JavacNode findInnerClass(JavacNode parent, String name) {
		this.annotationTargetNode = parent;
		parent = this.annotationTargetNode;
		for (JavacNode child : parent.down()) {
			if (child.getKind() != Kind.TYPE) continue;
			JCClassDecl td = (JCClassDecl) child.get();
			if (td.name.contentEquals(name)) return child;
		}
		return null;
	}

	public JavacNode findAnnotation(Class<? extends Annotation> type, JavacNode node) {
		this.annotationTargetNode = node;
		node = this.annotationTargetNode;
		return findAnnotation(type, node, false);
	}

	public JavacNode findAnnotation(Class<? extends Annotation> type, JavacNode node, boolean delete) {
		this.annotationTargetNode = node;
		node = this.annotationTargetNode;
		if (node == null) return null;
		if (type == null) return null;
		switch (node.getKind()) {
		case ARGUMENT:
		case FIELD:
		case LOCAL:
		case TYPE:
		case METHOD:
			for (JavacNode child : node.down()) {
				if (annotationTypeMatches(type, child)) {
					if (delete) deleteAnnotationIfNeccessary(child, type);
					return child;
				}
			}
			// intentional fallthrough
		default:
			return null;
		}
	}

	public boolean annotationTypeMatches(Class<? extends Annotation> type, JavacNode node) {
		this.annotationTargetNode = node;
		node = this.annotationTargetNode;
		if (node.getKind() != Kind.ANNOTATION) return false;
		return typeMatches(type, node, ((JCAnnotation) node.get()).annotationType);
	}

	public boolean annotationTypeMatches(String type, JavacNode node) {
		this.annotationTargetNode = node;
		node = this.annotationTargetNode;
		if (node.getKind() != Kind.ANNOTATION) return false;
		return typeMatches(type, node, ((JCAnnotation) node.get()).annotationType);
	}

	public boolean typeMatches(Class<?> type, JavacNode node, JCTree typeNode) {
		this.annotationTargetNode = node;
		node = this.annotationTargetNode;
		return typeMatches(type.getName(), node, typeNode);
	}

	public boolean typeMatches(String type, JavacNode node, JCTree typeNode) {
		this.annotationTargetNode = node;
		node = this.annotationTargetNode;
		String typeName = typeNode == null ? null : typeNode.toString();
		if (typeName == null || typeName.length() == 0) return false;
		int lastIndexA = typeName.lastIndexOf('.') + 1;
		int lastIndexB = Math.max(type.lastIndexOf('.'), type.lastIndexOf('$')) + 1;
		int len = typeName.length() - lastIndexA;
		if (len != type.length() - lastIndexB) return false;
		for (int i = 0; i < len; i++) if (typeName.charAt(i + lastIndexA) != type.charAt(i + lastIndexB)) return false;
		TypeResolver resolver = node.getImportListAsTypeResolver();
		return resolver.typeMatches(node, type, typeName);
	}

	public boolean isFieldDeprecated(JavacNode field) {
		this.annotationTargetNode = field;
		field = this.annotationTargetNode;

